-- B runs in autocommit batches: never wrap this file in BEGIN. Reverse: reverse.sql.
\set ON_ERROR_STOP on
SELECT 'undated|' || publisher_id || '|' || count(*) || '|in window=' || count(*) FILTER (WHERE fetched_at > now() - interval '14 days')
  FROM articles WHERE publisher_id IN (8917, 8918, 8925, 8949, 8956) AND published_at IS NULL GROUP BY publisher_id ORDER BY publisher_id;
SET lock_timeout = '5s';
BEGIN;
DO $do$
DECLARE k int;
BEGIN
  UPDATE feeds SET parser_config = '{"date_after_label": "data-feather=\"clock\"", "utc_offset": "+00:00", "undated": "fetch_time"}'::jsonb
   WHERE publisher_id = 8917 AND feed_type = 'html' AND enabled AND parser_config = '{}'::jsonb;
  GET DIAGNOSTICS k = ROW_COUNT; IF k <> 1 THEN RAISE EXCEPTION '8917: % html feed rows with an empty parser_config, expected 1 - nothing changed', k; END IF;
  UPDATE feeds SET parser_config = '{"undated": "fetch_time"}'::jsonb
   WHERE publisher_id = 8918 AND feed_type = 'html' AND enabled AND parser_config = '{}'::jsonb;
  GET DIAGNOSTICS k = ROW_COUNT; IF k <> 1 THEN RAISE EXCEPTION '8918: % html feed rows with an empty parser_config, expected 1 - nothing changed', k; END IF;
  UPDATE feeds SET parser_config = '{"undated": "fetch_time"}'::jsonb
   WHERE publisher_id = 8925 AND feed_type = 'html' AND enabled AND parser_config = '{}'::jsonb;
  GET DIAGNOSTICS k = ROW_COUNT; IF k <> 1 THEN RAISE EXCEPTION '8925: % html feed rows with an empty parser_config, expected 1 - nothing changed', k; END IF;
END $do$;
SELECT 'config|' || publisher_id || '|' || parser_config::text FROM feeds WHERE publisher_id IN (8917, 8918, 8925, 8949, 8956) AND enabled ORDER BY publisher_id;
COMMIT;
CREATE TEMP TABLE batch_ids AS
  SELECT id, ((row_number() OVER (ORDER BY id)) - 1) / 500 AS b FROM articles
   WHERE publisher_id IN (8917, 8918, 8925, 8949, 8956) AND published_at IS NULL AND fetched_at > now() - interval '14 days';
CREATE INDEX ON batch_ids (b); ANALYZE batch_ids;
SELECT 'batches|' || count(*) || ' rows|' || coalesce(max(b) + 1, 0) || ' batches' FROM batch_ids;
SET statement_timeout = '15s';
SELECT 'DO $w$ BEGIN IF EXISTS (SELECT 1 FROM pg_stat_activity WHERE datname = current_database() AND pid <> pg_backend_pid() AND wait_event_type = ''Lock'' AND now() - query_start > interval ''30 seconds'') THEN RAISE EXCEPTION ''stopping: a session has waited on a lock for over 30s''; END IF; END $w$',
       format('UPDATE articles a SET published_at = a.fetched_at FROM batch_ids i WHERE i.b = %s AND a.id = i.id AND a.published_at IS NULL', b),
       'SELECT pg_sleep(4)'
  FROM generate_series(0, coalesce((SELECT max(b) FROM batch_ids), -1)) b ORDER BY b
\gexec
